def _ol(items):
    return '<ol class="e-ul">' + "".join(f"<li><b>{a}</b> — {b}</li>" for a, b in items) + "</ol>"


def _sheet(num, slug, title, sub, layers):
    """Без картинки: прежние семь листов альбома были перекошены при растровой выгрузке из PDF и убраны,
    послойный состав остаётся текстом. Авторские иллюстрации добавляются по мере готовности (см. list-08 в 3а)."""
    rows = "".join(f"<li><b>{i + 1}. {a}</b> — {b}</li>" for i, (a, b) in enumerate(layers))
    return (
        f'<p class="e-note"><b>{num}. {title}.</b> {sub}.</p>'
        f'<ol class="e-ul">{rows}</ol>'
    )


